<?php
$labels=['first_name'=>'نام','last_name'=>'نام خانوادگی','art_name'=>'نام هنری؛ اختیاری','website'=>'وب‌سایت؛ اختیاری','private_phone'=>'تلفن تماس خصوصی؛ اختیاری','private_email'=>'ایمیل تماس خصوصی؛ اختیاری'];
$socialValues=is_array($v['social']??null)?$v['social']:[];$otherLinks=[];$legacy=$v['social_links']??[];if(!is_array($legacy))$legacy=preg_split('/\R/u',$legacy,-1,PREG_SPLIT_NO_EMPTY);foreach($legacy as $link){$host=strtolower(parse_url($link,PHP_URL_HOST)??'');$key=match(preg_replace('/^www\./','',$host)){'instagram.com'=>'instagram','t.me','telegram.me'=>'telegram','eitaa.com'=>'eitaa',default=>''};if($key&&!isset($socialValues[$key]))$socialValues[$key]=$link;else $otherLinks[]=$link;}
?>
<p class="hint">فقط نام و نام خانوادگی الزامی است؛ بقیه اطلاعات را می‌توانید بعداً تکمیل کنید.</p>
<div class="fields"><?php foreach($labels as $key=>$label): ?><label><?= e($label) ?><input name="<?= e($key) ?>" maxlength="<?= $key==='website'?1000:($key==='private_email'?190:150) ?>" <?= in_array($key,['first_name','last_name'],true)?'required':'' ?> <?= $key==='private_email'?'type="email"':($key==='private_phone'?'type="tel"':'') ?> <?= $key==='website'?'dir="ltr" placeholder="example.com"':'' ?> value="<?= e($v[$key]??'') ?>"></label><?php endforeach ?>
<fieldset class="full"><legend>حوزه فعالیت هنری؛ اختیاری</legend><div class="artist-checks"><?php foreach($terms as $t):if($t['taxonomy']!=='art_specialty')continue; ?><label class="check"><input type="checkbox" name="specialties[]" value="<?= (int)$t['id'] ?>" <?= in_array((int)$t['id'],array_map('intval',$v['specialties']??[]),true)?'checked':'' ?>><?= e($t['title']) ?></label><?php endforeach ?></div></fieldset>
<?php foreach(['summary'=>'معرفی کوتاه؛ اختیاری','biography'=>'درباره من و معرفی هنری؛ اختیاری','awards'=>'سوابق فعالیت؛ اختیاری'] as $key=>$label): ?><label class="full"><?= e($label) ?><textarea name="<?= e($key) ?>" rows="<?= $key==='biography'?4:2 ?>" maxlength="<?= $key==='biography'?20000:($key==='awards'?10000:2000) ?>"><?= e($v[$key]??'') ?></textarea></label><?php endforeach ?>
<fieldset class="full artist-social-fields"><legend>شبکه‌های اجتماعی؛ اختیاری</legend>
<?php foreach(['instagram'=>['اینستاگرام','instagram.com/username'],'telegram'=>['تلگرام','t.me/username'],'eitaa'=>['ایتا','eitaa.com/username']] as $key=>[$label,$example]): ?><label class="artist-social-row"><span class="artist-social-name"><?= Namira\MobileNavigation::icon($key) ?><span><?= e($label) ?></span></span><input name="social[<?= $key ?>]" maxlength="1000" dir="ltr" placeholder="<?= e($example) ?>" value="<?= e($socialValues[$key]??'') ?>"></label><?php endforeach ?>
<p class="hint">نام کاربری، @username یا لینک کامل همان شبکه را وارد کنید.</p>
<?php if($otherLinks): ?><details><summary>سایر لینک‌های ثبت‌شده قبلی</summary><label>هر نشانی در یک خط<textarea name="social_links" rows="2" maxlength="5000"><?= e(implode("\n",$otherLinks)) ?></textarea></label></details><?php endif ?></fieldset>
<label class="full">تصویر پروفایل؛ اختیاری<input type="file" name="avatar" data-account-avatar accept=".jpg,.jpeg,.png,.webp"></label>
<?php if(!empty($application)): ?><label class="full">اطلاعات تماس تکمیلی؛ خصوصی و اختیاری<textarea name="contact_details" maxlength="3000" rows="2"><?= e($v['contact_details']??'') ?></textarea></label><label class="full">لینک نمونه‌کار؛ اختیاری<textarea name="sample_links" maxlength="5000" rows="2" dir="ltr" placeholder="example.com/portfolio"><?= e($v['sample_links']??'') ?></textarea><small>هر لینک در یک خط؛ فقط اگر نمونه‌کار آنلاین دارید.</small></label><label class="full">نمونه‌کار تصویری؛ اختیاری، حداکثر ۳ فایل<input type="file" name="samples[]" multiple accept=".jpg,.jpeg,.png,.webp"></label><?php endif ?></div>
<p class="hint" data-avatar-hint>فرمت تصویر: JPG، JPEG، PNG یا WebP. تصویر پروفایل پیش از ارسال بهینه می‌شود. اطلاعات تماس و نمونه‌کارهای عضویت خصوصی‌اند.</p>
